list_customer_groups.code:
var response = await client.CustomerGroups.ListCustomerGroupsAsync(
    new Dictionary<string, object?> { ["search_text"] = "wholesale", ["status"] = "active", ["limit"] = 50 });
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
foreach (var customerGroup in ((IReadOnlyList<object?>)body["customer_groups"]!).Cast<IReadOnlyDictionary<string, object?>>())
    Console.WriteLine($"{customerGroup["id"]} {customerGroup["name"]} {customerGroup["status"]}");
var pagination = (IReadOnlyDictionary<string, object?>)body["pagination"]!;
Console.WriteLine(pagination["total"]);

